#!/usr/bin/env bash
# Source only in the release step. These names do not determine the token type:
# both alternatives must contain credentials generated by Central Portal.
if [[ -n "${MAVEN_CENTRAL_USERNAME:-}" || -n "${MAVEN_CENTRAL_PASSWORD:-}" ]]; then
  if [[ -z "${MAVEN_CENTRAL_USERNAME:-}" || -z "${MAVEN_CENTRAL_PASSWORD:-}" ]]; then
    echo 'Unable to select Central credentials: set both MAVEN_CENTRAL_USERNAME and MAVEN_CENTRAL_PASSWORD.' >&2
    return 1
  fi
  export ORG_GRADLE_PROJECT_mavenCentralUsername="$MAVEN_CENTRAL_USERNAME"
  export ORG_GRADLE_PROJECT_mavenCentralPassword="$MAVEN_CENTRAL_PASSWORD"
else
  if [[ -z "${OSSRH_USERNAME:-}" || -z "${OSSRH_PASSWORD:-}" ]]; then
    echo 'Unable to select Central credentials: set a complete MAVEN_CENTRAL_* or OSSRH_* pair.' >&2
    return 1
  fi
  export ORG_GRADLE_PROJECT_mavenCentralUsername="$OSSRH_USERNAME"
  export ORG_GRADLE_PROJECT_mavenCentralPassword="$OSSRH_PASSWORD"
fi
